I execute script () => {
  const select = document.getElementById("cboxtypeId");
  if (select) {
    select.value = "INE";
    ['input', 'change', 'blur'].forEach(evtType => {
      const evt = new Event(evtType, { bubbles: true });
      select.dispatchEvent(evt);
    });
  }
}

